import{_ as n}from"./chunks/files.B17OUyrr.js";import{_ as i,c as r,o as t,a2 as a}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"qDiff kennenlernen","description":"Eine kurze Einführung in den Vergleich von Dateien, Ordnern und Projekten mit qDiff auf Ihrem Mac.","frontmatter":{"title":"qDiff kennenlernen","description":"Eine kurze Einführung in den Vergleich von Dateien, Ordnern und Projekten mit qDiff auf Ihrem Mac."},"headers":[],"relativePath":"de/guide/introduction.md","filePath":"de/guide/introduction.md","lastUpdated":1794296122000}'),s={name:"de/guide/introduction.md"};function d(l,e,o,h,u,c){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="qdiff-kennenlernen" tabindex="-1">qDiff kennenlernen <a class="header-anchor" href="#qdiff-kennenlernen" aria-label="Permalink to &quot;qDiff kennenlernen&quot;">​</a></h1><p>qDiff beantwortet eine Frage: <strong>Was hat sich geändert?</strong> Stellen Sie zwei Versionen nebeneinander, und alles Abweichende wird farbig markiert, sodass Sie nicht mehr Zeile für Zeile mit den Augen vergleichen müssen.</p><img src="'+n+'" alt="Zwei Dateien im Vergleich nebeneinander" class="guide-shot"><h2 id="drei-dinge-fur-die-es-genutzt-wird" tabindex="-1">Drei Dinge, für die es genutzt wird <a class="header-anchor" href="#drei-dinge-fur-die-es-genutzt-wird" aria-label="Permalink to &quot;Drei Dinge, für die es genutzt wird&quot;">​</a></h2><ul><li><strong>Zwei Dateien</strong> — ein Entwurf und seine Überarbeitung, eine Konfiguration vorher und nachher, zwei Exporte desselben Werkzeugs. Geänderte Wörter werden innerhalb der Zeile hervorgehoben.</li><li><strong>Zwei Ordner</strong> — ein Arbeitsordner und seine Sicherung. Neue, geänderte und fehlende Dateien sind leicht zu erkennen, und Sie können beide Seiten wieder in Einklang bringen.</li><li><strong>Ein Projektordner</strong> — alles, was Sie bearbeitet haben, in einer Liste zusammengefasst. Lesen Sie jede Änderung und führen Sie den Commit aus, ohne das Fenster zu wechseln.</li></ul><p>Auch Bilder, komprimierte Archive und Dateien, die kein reiner Text sind, sind willkommen. <a href="./more.html">Weitere Vergleichsmöglichkeiten</a>.</p><h2 id="in-drei-schritten-starten" tabindex="-1">In drei Schritten starten <a class="header-anchor" href="#in-drei-schritten-starten" aria-label="Permalink to &quot;In drei Schritten starten&quot;">​</a></h2><ol><li>Öffnen Sie qDiff und ziehen Sie zwei Dateien oder Ordner ins Fenster — oder wählen Sie sie im Ablage-Menü aus.</li><li>Sehen Sie sich die farbigen Zeilen an. Klicken Sie auf die kleine Übersicht an der Seite oder nutzen Sie die Schalter für Zurück / Weiter, um alle Änderungen durchzugehen.</li><li>Bearbeiten, kopieren oder synchronisieren Sie, was korrigiert werden muss. Speichern Sie ein Bild des Vergleichs, wenn es jemand anderes sehen soll.</li></ol><div class="tip custom-block"><p class="custom-block-title">Keine Einrichtung nötig</p><p>Sie müssen kein Konto erstellen und vor dem ersten Vergleich nichts konfigurieren. Alles funktioniert offline.</p></div><h2 id="kostenlos-und-privat" tabindex="-1">Kostenlos und privat <a class="header-anchor" href="#kostenlos-und-privat" aria-label="Permalink to &quot;Kostenlos und privat&quot;">​</a></h2><p>Jeder Vergleich ist kostenlos verfügbar. Die kostenlose Version zeigt lediglich einen kleinen Hinweis in der Tableiste; ein einmaliger Kauf entfernt ihn. qDiff liest nur die Dateien, die Sie auswählen, und sendet nichts an irgendwohin — Details finden Sie in der <a href="./../privacy/">Datenschutzerklärung</a>.</p><h2 id="brauchen-sie-hilfe" tabindex="-1">Brauchen Sie Hilfe? <a class="header-anchor" href="#brauchen-sie-hilfe" aria-label="Permalink to &quot;Brauchen Sie Hilfe?&quot;">​</a></h2><p>Die <a href="./faq.html">FAQ</a> beantwortet die häufigsten Fragen. Falls dennoch etwas nicht stimmt, <a href="./../guide/support.html">schreiben Sie uns</a> und wir helfen weiter.</p>',13)])])}const k=i(s,[["render",d]]);export{m as __pageData,k as default};
